1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Models;
6	
7	use App\Concerns\LogsCatalogActivity;
8	use AtrioTeam\DigitalHub\Assets\Concerns\HasAssets;
9	use AtrioTeam\DigitalHub\Assets\Contracts\OwnsAssets;
10	use AtrioTeam\DigitalHub\Identity\Concerns\HasGlobalId;
