17	/**
18	 * `app:sync-outdoor-fabric-products`: Outdoor non ha una matrice come
19	 * Interior, ogni tessuto Outdoor va associato a ogni prodotto Outdoor. I
20	 * prodotti/tessuti Indoor non vanno toccati.
21	 */
22	class SyncOutdoorFabricProductsTest extends TestCase
23	{
24	    use RefreshDatabase;
25	
26	    private function destination(string $slug): Category1
27	    {
28	        return Category1::create(['name' => ['it' => ucfirst($slug)], 'slug' => $slug]);
29	    }
30	
31	    private function fabric(string $code, Category1 $destination): Fabric
32	    {
33	        $category = FabricCategory::create([
34	            'name' => ['it' => "Tipo {$code}"],
35	            'slug' => "tipo-{$code}",
36	            'category_1_id' => $destination->id,
37	        ]);
38	
39	        return Fabric::create([
40	            'fabric_category_id' => $category->id,
41	            'code' => $code,
42	            'name' => ['it' => "Tessuto {$code}"],
43	            'slug' => strtolower($code),
44	        ]);
45	    }
46	
47	    private function product(string $name, Category1 $destination): Product
48	    {
49	        $category2 = Category2::create(['name' => ['it' => "Collezione {$name}"], 'category_1_id' => $destination->id]);
50	        $productType = ProductType::firstOrCreate(
51	            ['slug' => 'tavolo'],
52	            ['name' => ['it' => 'Tavolo'], 'attribute_schema_class' => ProductAttributes::class],
53	        );
54	
55	        return Product::create([
56	            'name' => ['it' => $name],
57	            'category_2_id' => $category2->id,
58	            'product_type_id' => $productType->id,
59	        ]);
60	    }
61	
62	    public function test_it_links_every_outdoor_fabric_to_every_outdoor_product(): void
63	    {
64	        $outdoor = $this->destination('outdoor');
65	        $indoor = $this->destination('indoor');
66	
67	        $fabricA = $this->fabric('CA019', $outdoor);
68	        $fabricB = $this->fabric('CC101', $outdoor);
69	        $indoorFabric = $this->fabric('VL015', $indoor);
70	
71	        $productA = $this->product('Tavolo A', $outdoor);
72	        $productB = $this->product('Tavolo B', $outdoor);
73	        $indoorProduct = $this->product('Divano Indoor', $indoor);
74	
75	        $this->artisan('app:sync-outdoor-fabric-products')->assertSuccessful();
76	
77	        $this->assertEqualsCanonicalizing(
78	            [$fabricA->id, $fabricB->id],
79	            $productA->fresh()->fabrics->pluck('id')->all(),
80	        );
81	        $this->assertEqualsCanonicalizing(
82	            [$fabricA->id, $fabricB->id],
83	            $productB->fresh()->fabrics->pluck('id')->all(),
84	        );
85	
86	        // Indoor non è toccato: né come prodotto (nessun tessuto assegnato),
87	        // né come tessuto (non compare su nessun prodotto Outdoor)
88	        $this->assertCount(0, $indoorProduct->fresh()->fabrics);
89	        $this->assertFalse($productA->fresh()->fabrics->contains('id', $indoorFabric->id));
90	    }
91	
92	    public function test_reimport_is_idempotent_and_drops_stale_links(): void
93	    {
94	        $outdoor = $this->destination('outdoor');
95	        $indoor = $this->destination('indoor');
96	        $fabricA = $this->fabric('CA019', $outdoor);
97	        $product = $this->product('Tavolo A', $outdoor);
98	
99	        // associazione errata preesistente: un tessuto Indoor finito per
100	        // sbaglio su un prodotto Outdoor. sync() deve toglierlo, non solo
