102	        $wrongFabric = $this->fabric('VL015', $indoor);
103	        $product->fabrics()->attach($wrongFabric->id);
104	
105	        $this->artisan('app:sync-outdoor-fabric-products')->assertSuccessful();
106	
107	        $this->assertSame([$fabricA->id], $product->fresh()->fabrics->pluck('id')->all());
108	    }
