110	    public function test_it_fails_when_there_are_no_outdoor_fabrics(): void
111	    {
112	        $outdoor = $this->destination('outdoor');
113	        $this->product('Tavolo A', $outdoor);
114	
115	        $this->artisan('app:sync-outdoor-fabric-products')
116	            ->expectsOutputToContain('app:import-fabrics')
